import assert from 'node:assert/strict';
import {createServer} from 'node:http';
import {readFile,writeFile} from 'node:fs/promises';
import {sha256} from '../../packages/contracts/src/index.ts';
import {until} from '../acceptance/harness.ts';
import {assetPin,meridianModule} from './meridian-flow.ts';
import {stageReceiptFlow} from './stage-receipt-flow.ts';

// Synthetic staged receipts only. The gate lets tests stop between durable D
// completion and an ordinary result read without modifying task or run state.
export async function resultReadFlow(t:any){
 const f=await stageReceiptFlow(t),{h}=f,state=Object.assign(f.state,{gate:false,resultReads:0,badSha:false}),file=h.env.CIRCLE_HUB_EXECUTION_GATEWAYS!,previous=JSON.parse(await readFile(file,'utf8')).profiles.fixture;
 const gateTool={name:'read_gate',description:'Synthetic result-read synchronization gate',minimumRole:'member',approval:false,effect:'read',annotations:{readOnlyHint:true},inputSchema:{type:'object',properties:{},required:[],additionalProperties:false}};
 const proxy=createServer(async(req,res)=>{try{const chunks=[];for await(const chunk of req)chunks.push(chunk);const rpc=JSON.parse(Buffer.concat(chunks).toString());let result:any;if(rpc.method==='tools/call'&&rpc.params.name==='read_gate'){const raw={ok:true,ready:state.gate};result={structuredContent:raw,content:[{type:'text',text:JSON.stringify(raw)}]};}else{const response=await fetch(previous.endpoint,{method:'POST',headers:{'content-type':'application/json',authorization:String(req.headers.authorization??'')},body:JSON.stringify(rpc)}),body=await response.json();result=body.result;if(rpc.method==='tools/list')result={tools:[...result.tools,gateTool]};if(rpc.method==='tools/call'&&rpc.params.name==='results'){state.resultReads++;if(state.badSha){const raw={...result.structuredContent,xlsx_sha256:'0'.repeat(64)};result={...result,structuredContent:raw,content:[{type:'text',text:JSON.stringify(raw)}]};}}}res.setHeader('content-type','application/json');res.end(JSON.stringify({jsonrpc:'2.0',id:rpc.id,result}));}catch{if(!res.destroyed){res.writeHead(502);res.end();}}});
 await new Promise<void>(resolve=>proxy.listen(0,'127.0.0.1',resolve));t.after(async()=>{proxy.closeAllConnections();await new Promise<void>(resolve=>proxy.close(()=>resolve()));});const profile={...previous,endpoint:`http://127.0.0.1:${(proxy.address() as any).port}/mcp`};await writeFile(file,JSON.stringify({profiles:{fixture:profile}}));await h.stop();await h.startServer();
 // startServer's existing harness path explicitly registers and independently
 // approves the changed fixture runtime; its profileRef has one asset identity.
 const old=await h.request(`/v1/assets/${f.resource.assetId}`),resource=await h.request('/v1/assets',{assetId:old.assetId,scopeId:'scp_lab',kind:old.kind,name:old.name,version:'3.0.0',configuration:old.configuration,declaration:{...old.declaration,provides:{tools:[...old.declaration.provides.tools,gateTool]}},readers:['prn_alice','prn_bob']});await h.request(`/v1/assets/${resource.assetId}/lifecycle`,{version:resource.version,sha256:resource.sha256,state:'approved'},'bob');await h.request(`/v1/assets/${resource.assetId}/lifecycle`,{version:resource.version,sha256:resource.sha256,state:'running'});
 const fixture=await meridianModule('1.0.0','result-read-fixture','result-read-flow'),manifestFile=fixture.files.find(file=>file.path==='product-line.json'),manifest=JSON.parse(Buffer.from(manifestFile.base64,'base64').toString());manifest.tools.push({manifest:'tools/workbook.ts',imports:{}});manifestFile.base64=Buffer.from(JSON.stringify(manifest)).toString('base64');fixture.files.push({path:'tools/workbook.ts',base64:Buffer.from("export async function readBook(_metadata,bytes){const book=JSON.parse(new TextDecoder().decode(bytes)),hash=new Uint8Array(await crypto.subtle.digest('SHA-256',bytes));return {sha256:Array.from(hash).map(n=>n.toString(16).padStart(2,'0')).join(''),cases:book.cases};}").toString('base64'),sha256:''});
 fixture.files.find(file=>file.path==='tools/transition.ts').base64=Buffer.from(`
export function transition(input){
 const state=input.state,find=id=>input.observations.find(row=>row.facts.stepId===id),a=(kind,stepId,fields)=>({kind,stepId,occurrence:0,...fields}),out=(stage,actions,extra={})=>({schema:'hub-execution-transition/1',state:{stage,...extra},actions});
 const candidate=()=>{const read=find('read-results'),failed=read.facts.status!=='succeeded',raw=read.facts.result;return {cases:failed?[]:raw.cases??[],channel:failed?'unavailable':raw.channel??'unavailable',rc:failed?null:raw.rc??null,unmapped:failed?[{operationId:read.operationId,reason:'result_read_unavailable',code:read.facts.error?.code??'INTERNAL_ERROR'}]:[],...(failed?{error:read.facts.error}:{})};};
 if(state.stage==='prepare')return out('projected',[a('tool.call','project',{path:'tools/workbook.ts',export:'readBook',args:[{}],byteSlots:['workbook']})]);
 if(state.stage==='projected')return out('submitted',[a('provider.call','submit',{resource:'gateway',tool:'submit',args:{},byteArgs:{payload:'workbook'}})]);
 if(state.stage==='submitted')return out('gated',[a('provider.call','gate-0',{resource:'gateway',tool:'read_gate',args:{}})],{gate:0});
 if(state.stage==='gated'){const gate=find('gate-'+state.gate);if(!gate.facts.result.ready)return out('gated',[a('provider.call','gate-'+(state.gate+1),{resource:'gateway',tool:'read_gate',args:{}})],{gate:state.gate+1});return out('read',[a('provider.call','read-results',{resource:'gateway',tool:'results',args:{task_id:find('submit').facts.result.task_id}})]);}
 if(state.stage==='read')return out('hooked',[a('hook.verify','after-result',{event:'afterResult',subject:{operationId:find('submit').operationId,result:candidate()}})]);
 if(state.stage==='hooked')return out('done',[a('delivery.propose','deliver',{status:find('read-results').facts.status==='succeeded'?'succeeded':'partial',result:candidate(),references:input.observations.map(row=>row.reference)})]);
 return out(state.stage,[]);
}`).toString('base64');
 for(const file of fixture.files)file.sha256=sha256(Buffer.from(file.base64,'base64'));fixture.files.sort((a,b)=>a.path<b.path?-1:a.path>b.path?1:0);fixture.module.files=fixture.files.map(({path,sha256})=>({path,sha256}));fixture.module.digest=sha256(fixture.module.files.map(file=>`${file.sha256}  ${file.path}\n`).join(''));const installed=await h.raw('/v1/modules/install',{token:await h.login(),headers:{'x-scope-id':'scp_lab'},body:fixture});assert.equal(installed.status,201,JSON.stringify(installed.body));const method=installed.body.data;await h.request(`/v1/assets/${method.assetId}/lifecycle`,{version:method.assetVersion,sha256:method.assetSha256,state:'approved'},'bob');
 const input=()=>({...f.input(),flowId:'result-read-flow',methodPin:assetPin(method),resources:{gateway:assetPin(resource)}}),submit=(key:string)=>h.request('/v1/tasks/submit',{scopeId:'scp_lab',capabilityPackId:'module-execute',idempotencyKey:key,input:input()});
 async function reconciled(key:string,workerEnv:Record<string,string>={}){f.state.refuseStatus=true;const first=await h.startWorker(),task=await submit(key);await h.phase(task.taskId,'unknown',30_000);const parent=(await h.db.query("SELECT o.*,s.remote_identity FROM operations o JOIN flow_steps s USING(operation_id) WHERE o.task_id=$1 AND o.source_effect='write'",[task.taskId])).rows[0];await h.stop(first);f.state.refuseStatus=false;await h.request(`/v1/tasks/${task.taskId}/reconcile`,{operationId:parent.operation_id});const worker=await h.startWorker('lab-east-02',workerEnv);await until(async()=>(await h.db.query('SELECT status FROM operations WHERE operation_id=$1',[parent.operation_id])).rows[0]?.status==='reconciled',30_000);await until(async()=>(await h.db.query("SELECT 1 FROM flow_steps WHERE task_id=$1 AND step_id LIKE 'gate-%'",[task.taskId])).rowCount,30_000);return {task,parent,worker};}
 return {...f,state,h,method,resource,input,submit,reconciled};
}

export async function resultReadReportProxy(t:any,h:any,options:{forgeSuccess?:boolean;beforeReport?:(operationId:string,body:any)=>Promise<void>}={}){
 let changed:any;const proxy=createServer(async(req,res)=>{try{const chunks=[];for await(const chunk of req)chunks.push(chunk);let bytes=Buffer.concat(chunks);const route=/^\/v1\/workers\/operations\/([^/]+)\/report$/.exec(req.url??'');if(route&&bytes.length){const step=(await h.db.query('SELECT step_id FROM flow_steps WHERE operation_id=$1',[route[1]])).rows[0];const body=JSON.parse(bytes.toString());if(step?.step_id==='read-results'){if(options.forgeSuccess){const pointer=body.output?.unverifiedReceiptPointer?.pointer??body.output?.resultPointer;assert.ok(pointer);body.status='succeeded';body.output={resultPointer:pointer};delete body.error;}await options.beforeReport?.(route[1],body);changed={operationId:route[1],body};bytes=Buffer.from(JSON.stringify(body));}}const headers:Record<string,string>={};for(const key of ['authorization','content-type'])if(typeof req.headers[key]==='string')headers[key]=req.headers[key];const response=await fetch(h.url+(req.url??'/'),{method:req.method,headers,...(bytes.length?{body:bytes}:{})});res.writeHead(response.status,{'content-type':'application/json'});res.end(Buffer.from(await response.arrayBuffer()));}catch{if(!res.destroyed){res.writeHead(502);res.end();}}});await new Promise<void>(resolve=>proxy.listen(0,'127.0.0.1',resolve));t.after(async()=>{proxy.closeAllConnections();await new Promise<void>(resolve=>proxy.close(()=>resolve()));});return {url:`http://127.0.0.1:${(proxy.address() as any).port}`,changed:()=>changed};
}

export const forgeSuccessfulResultRead=(t:any,h:any)=>resultReadReportProxy(t,h,{forgeSuccess:true});
